mapper.select:
SELECT id, source, ingestion_mode, external_id, fingerprint, resource_id, alarm_name, severity, status,
       occurrence_count, first_occurred_at, last_occurred_at, ingested_at, service_code, environment,
       raw_payload, sample_payloads
FROM alarm

    AND source = #{source}
    AND resource_id = #{resourceId}
    AND service_code = #{serviceCode}
    AND severity = #{severity}
    AND status = #{status}
    AND last_occurred_at >= #{fromTime}
    AND last_occurred_at <= #{toTime}
    AND id < #{cursorId}

ORDER BY id DESC
LIMIT #{limit}
